var l=[{title:`Поширене твердження`,text:`Сотні скручувань часто продають як спосіб позбутися жиру на животі, а вправи для внутрішньої поверхні стегна рекламують як спосіб цілеспрямовано впливати на жир там. Робочі м’язи справді стають сильнішими чи кращими у тривалому зусиллі. Використання м’яза все одно не дає надійного контролю над жиром поруч із ним.`},{title:`Що кажуть дослідження`,text:`Зміни жиру в тілі залежать від енергетичного балансу, генетики, гормонів і загальної активності. Практичні поради щодо тренувань не повинні обіцяти точної втрати жиру з однієї ділянки. Дослідження не зовсім однозначні: невелике випробування 2023 року виявило більшу втрату жиру на тулубі за одного конкретного протоколу витривалості для преса. Цей результат не показує, що звичайні скручування надійно визначають, де будь-яка людина втрачає жир.`},{title:`Що робить цілеспрямоване тренування`,text:`Планки, згинання рук, випади та інші вправи можуть покращувати силу, витривалість і функцію м’язів, на які вони працюють. Поєднуйте силові тренування з аеробною активністю для ширшого здоров’я та форми. Те, скільки жиру ви втрачаєте, не є прямою мірою того, наскільки гарні ваші вправи.`},{title:`Приклад`,text:`Якщо ви хочете сильніший кор, практикуйте «мертвого жука», бічні планки та перенесення вантажу. Вони розвивають силу та витривалість тулуба незалежно від того, чи змінюється ваш обхват талії цього місяця.`},{title:`Як це працює в TrainUp`,text:`Кожна сторінка вправи у розділі Вправи показує м’язи, на які працює вправа, та її руховий патерн. Саме це вправа й тренує.`}];var i=[{label:`Рандомізоване дослідження 2023 року про регіональні вправи та зміну жиру`,url:`https://pubmed.ncbi.nlm.nih.gov/38010201/`},{label:`Вправи та зміни абдомінального жиру`,url:`https://pubmed.ncbi.nlm.nih.gov/16002776/`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:l,sources:i};export{n as default,l as sections,i as sources};